SELECT m.chembl_id, m.pref_name, cs.canonical_smiles, di.efo_id AS indication_curie, di.mesh_heading AS indication_label, di.max_phase_for_ind FROM molecule_dictionary m LEFT JOIN compound_structures cs ON m.molregno = cs.molregno JOIN drug_indication di ON m.molregno = di.molregno WHERE di.mesh_heading = 'Non-Small Cell Lung Carcinoma' ORDER BY m.chembl_id, m.pref_name, cs.canonical_smiles, di.efo_id, di.mesh_heading, di.max_phase_for_ind
